        ["baseline-published/megadock/megadock-gpu", "-R", "{spec:/prepared/receptor}", "-L", "{spec:/prepared/ligand}", "-o", "{out}/docking.out", "-N", "50", "-t", "1", "-v", "1.2", "-e", "1", "-d", "1", "-a", "-45.0", "-b", "1", "-f", "3", "-D"],
        ["bash", "-c", "set -euo pipefail; for r in $(seq 1 50); do baseline-published/megadock/decoygen \"lig_$r.pdb\" \"$2\" \"$0/docking.out\" \"$r\" > \"decoygen_$r.log\" 2>&1; grep -v '^END' \"$1\" > \"$0/model_$r.pdb\"; grep -v -E '^(END|ENDMDL)' \"lig_$r.pdb\" >> \"$0/model_$r.pdb\"; echo END >> \"$0/model_$r.pdb\"; done", "{out}", "{spec:/prepared/receptor}", "{spec:/prepared/ligand}"]
      ],
      "env": {"OMP_NUM_THREADS": "{spec:/omp_threads/tens}{spec:/omp_threads/ones}", "OMP_DYNAMIC": "FALSE", "OPENBLAS_NUM_THREADS": "1", "MKL_NUM_THREADS": "1", "NUMEXPR_NUM_THREADS": "1", "LC_ALL": "C", "LANG": "C", "CUDA_VISIBLE_DEVICES": "0"}
